"""`agentbisect` entrypoint: investigate (intake + plain bisect), resume, status; watch is a later chunk."""
from __future__ import annotations

import argparse
import contextlib
import json
import os
import sys

from .intake import (FixtureSource, IntakeError, IntakeResult, NeatlogsCliSource, WaitingOnHumanLogin,
                     intake_detection, intake_issue, intake_trace)
from .models import BisectState
from .state import DEFAULT_DIR, StateError, StateStore
from .verify import describe_revert
from .tracing import init_tracing, shutdown_tracing


def _summary(st: BisectState) -> str:
    verdicts = {s: r.verdict for s, r in st.results.items()}
    tokens = sum(t["tokens"] for t in st.context_tokens_per_step)
    lines = [f"investigation {st.id}  status={st.status}  step={st.step}  repo={st.repo}",
             f"  range: good={st.good_sha or '?'} bad={st.bad_sha or '?'}  mode={st.plan.mode if st.plan else '-'}",
             f"  commits tested: {len(verdicts)}  " + " ".join(f"{s[:8]}={v}" for s, v in verdicts.items()),
             f"  context tokens logged: {tokens} over {len(st.context_tokens_per_step)} entries"]
    if st.in_flight:
        lines.append(f"  INTERRUPTED mid-step: {st.in_flight}")
    if st.error:
        lines.append(f"  error: {st.error}")
    lines += describe_revert(st)
    return "\n".join(lines)


def _add_intake_args(p: argparse.ArgumentParser) -> None:
    g = p.add_mutually_exclusive_group(required=True)
    g.add_argument("--trace", help="neatlogs trace id of a bad run")
    g.add_argument("--detection", help="neatlogs detection id")
    g.add_argument("--issue", help="GitHub issue URL (read with `gh issue view`)")
    p.add_argument("--repo", required=True, help="path to the target repo (has evals/cases.jsonl)")
    p.add_argument("--fixtures", help="recorded JSON trace fixtures instead of the live neatlogs CLI")
    p.add_argument("--project", help="neatlogs project uuid (default $NEATLOGS_PROJECT_ID)")
    p.add_argument("--workflow", default="support-agent", help="neatlogs workflow name of the target's runs")
    p.add_argument("--strategy", choices=["smart", "plain"], default="smart",
                   help="bisect strategy run after intake (default smart: rank commits by trace divergence, "
                        "code impact and checkpoint intent, then fall back to plain)")
    p.add_argument("--llm-proxy", default="off", metavar="auto|URL|off",
                   help="route the target's Anthropic calls through the local `claude`-CLI proxy: auto = start one "
                        "for this run, URL = use a running one, off (default) = use the real API key")
    p.add_argument("--intake-only", action="store_true", help="stop after intake; do not run the bisect")
    p.add_argument("--good", help="known-good commit (overrides the one intake found)")
    p.add_argument("--bad", help="known-bad commit (default: failing trace's commit, else HEAD)")


def trace_source(a: argparse.Namespace | None = None, meta: dict | None = None):
    """Trace source for span divergence; `meta` ({fixtures, project}) comes from a saved investigation."""
    fixtures = getattr(a, "fixtures", None) if a else (meta or {}).get("fixtures")
    project = getattr(a, "project", None) if a else (meta or {}).get("project")
    return FixtureSource(fixtures) if fixtures else NeatlogsCliSource(project=project)


def make_strategy(st: BisectState, store: StateStore, meta: dict | None = None):
    """Strategy for an investigation: None means the engine default (plain)."""
    if st.metrics.get("strategy", "plain") != "smart":
        return None
    from .planner import Planner, SmartStrategy
    try:
        source = trace_source(meta=meta)
    except Exception:  # no usable trace source: the planner ranks by checkpoint intent alone
        source = None
    return SmartStrategy(Planner(st.repo, source=source), store)


def run_intake(a: argparse.Namespace) -> IntakeResult:
    if a.issue:
        return intake_issue(a.issue, a.repo)
    src = FixtureSource(a.fixtures) if a.fixtures else NeatlogsCliSource(project=a.project)
    if a.trace:
        return intake_trace(src, a.trace, a.repo, workflow=a.workflow)
    return intake_detection(src, a.detection, a.repo, workflow=a.workflow)


def _parser() -> argparse.ArgumentParser:
    p = argparse.ArgumentParser(prog="agentbisect", description="git bisect for agent behavior")
    p.add_argument("--state-dir", default=DEFAULT_DIR, help=f"state directory (default {DEFAULT_DIR})")
    sub = p.add_subparsers(dest="cmd", required=True)
    inv = sub.add_parser("investigate", help="run intake and record the RegressionSpec in a new investigation")
    _add_intake_args(inv)
    _add_intake_args(sub.add_parser("intake", help="run intake and print the RegressionSpec (no state written)"))
    c = sub.add_parser("compare", help="run plain and smart bisect on one investigation (separate empty caches) "
                                       "and print eval rounds and cost")
    c.add_argument("id")
    c.add_argument("--fixtures", help="recorded trace fixtures for the smart planner's span divergence")
    c.add_argument("--project", help="neatlogs project uuid")
    rp = sub.add_parser("report", help="write the Markdown/HTML report; optionally open a PR (dry-run by default)")
    rp.add_argument("id")
    rp.add_argument("--format", choices=["md", "html", "both"], default="both")
    rp.add_argument("--out", help="output directory (default: evidence/ in the agentbisect repo)")
    rp.add_argument("--open-pr", action="store_true", help="prepare a PR from the best fix branch (dry-run)")
    rp.add_argument("--confirm-open-pr", action="store_true",
                    help="really `git push` and `gh pr create` (requires --open-pr)")
    rp.add_argument("--draft", action="store_true", help="force a draft PR (default: draft iff the fix is unverified)")
    lp = sub.add_parser("llm-proxy", help="serve an Anthropic-compatible API backed by your logged-in `claude` CLI")
    lp.add_argument("--port", type=int, default=8787)
    lp.add_argument("--concurrency", type=int, default=3)
    lp.add_argument("--cache", action="store_true", help="cache responses in .agentbisect/llm_cache")
    lp.add_argument("--cache-dir")
    lp.add_argument("--debug-dump", metavar="DIR", help="DEBUG: write every rendered prompt + output to DIR (use /tmp)")
    sub.add_parser("watch", help="poll neatlogs detections and auto-investigate (not implemented yet)")
    r = sub.add_parser("resume", help="resume an interrupted investigation")
    r.add_argument("id")
    s = sub.add_parser("status", help="show investigations")
    s.add_argument("id", nargs="?")
    return p


def main(argv: list[str] | None = None) -> int:
    a = _parser().parse_args(argv)
    store = StateStore(a.state_dir)
    if a.cmd == "llm-proxy":
        from .llm_proxy import run_forever
        return run_forever(a.port, a.concurrency, a.cache, a.cache_dir, debug_dump=a.debug_dump)
    if a.cmd == "investigate":
        with _llm_proxy(getattr(a, "llm_proxy", "off")):
            return _main(a, store)
    return _main(a, store)


@contextlib.contextmanager
def _llm_proxy(mode: str):
    """`auto` starts an in-process proxy for the duration; a URL is used as is. Runners read the env var."""
    px = None
    prev = os.environ.get("AGENTBISECT_LLM_PROXY_URL")
    if mode == "auto":
        from .llm_proxy import LLMProxy
        px = LLMProxy(cache_dir=".agentbisect/llm_cache")
        px.serve(0)
        os.environ["AGENTBISECT_LLM_PROXY_URL"] = px.url
        print(f"llm proxy (own claude login) at {px.url}", file=sys.stderr)
    elif mode and mode != "off":
        os.environ["AGENTBISECT_LLM_PROXY_URL"] = mode
    try:
        yield
    finally:
        if px:
            print(f"llm proxy stats: {json.dumps(px.stats.snapshot())}", file=sys.stderr)
            px.stop()
        if prev is None:
            os.environ.pop("AGENTBISECT_LLM_PROXY_URL", None)
        else:
            os.environ["AGENTBISECT_LLM_PROXY_URL"] = prev


def _main(a: argparse.Namespace, store: StateStore) -> int:
    if a.cmd in ("investigate", "intake"):
        try:
            res = run_intake(a)
        except WaitingOnHumanLogin as e:
            print(f"error: {e}", file=sys.stderr)
            return 3
        except IntakeError as e:
            print(f"error: {e}", file=sys.stderr)
            return 1
        if a.cmd == "intake":
            print(json.dumps(res.to_dict(), indent=2))
            return 0
        st = store.create(a.repo, spec=res.spec, good_sha=res.good_sha, bad_sha=res.bad_sha)
        print(f"investigation {st.id} created (status={st.status}); spec: {len(res.spec.cases)} cases, "
              f"{len(res.spec.held_out)} held out, {len(res.spec.good_trace_ids)} good traces, "
              f"range good={res.good_sha or '?'} bad={res.bad_sha or '?'}")
        for n in res.notes:
            print(f"  - {n}")
        if a.good:
            st.good_sha = a.good
        if a.bad:
            st.bad_sha = a.bad
        store.save(st)
        meta = {"fixtures": a.fixtures, "project": a.project}
        st.metrics["strategy"] = a.strategy
        st.metrics["source"] = meta
        store.save(st)
        if a.intake_only:
            print("intake only; run `agentbisect resume " + st.id + "` to bisect")
            return 0
        from .bisect import resume_investigation
        init_tracing(st.id)
        try:
            return _explain(store, st, int(resume_investigation(store, st, strategy=make_strategy(st, store, meta))),
                            meta)
        finally:
            shutdown_tracing()
    if a.cmd == "watch":
        print("agentbisect watch: not implemented yet (later chunk)", file=sys.stderr)
        return 2
    try:
        if a.cmd == "compare":
            return _compare(a, store)
        if a.cmd == "report":
            return _report(a, store)
        if a.cmd == "status":
            states = [store.load(a.id)] if a.id else store.list()
            if not states:
                print("no investigations")
            for st in states:
                print(_summary(st))
            return 0
        st = store.load(a.id)
        redo = store.resume(st)
        init_tracing(st.id)
        try:
            print(f"resumed {st.id}" + (f"; will redo interrupted step: {redo}" if redo else ""))
            from .bisect import resume_investigation
            meta = st.metrics.get("source")
            return _explain(store, st, int(resume_investigation(store, st, strategy=make_strategy(
                st, store, meta)) or 0), meta)
        finally:
            shutdown_tracing()
    except StateError as e:
        print(f"error: {e}", file=sys.stderr)
        return 1


def _explain(store: StateStore, st: BisectState, code: int, meta: dict | None) -> int:
    """After a bisect that found a culprit: culprit analysis, then the revert test (both resume-safe)."""
    if code != 0 or st.status != "culprit_found" or not st.culprit:
        return code
    from .verify import confirm_culprit
    try:
        source = trace_source(meta=meta)
    except Exception:
        source = None
    try:
        confirm_culprit(store, st, source=source)
    except Exception as e:  # keep the culprit; `resume` redoes the interrupted step
        print(f"error during culprit analysis / revert test: {type(e).__name__}: {e}", file=sys.stderr)
        return 1
    print("\n".join(describe_revert(st)))
    return 0


def _compare(a: argparse.Namespace, store: StateStore) -> int:
    from .bisect import make_runner
    from .planner import Planner, SmartStrategy, compare_strategies, format_comparison
    st = store.load(a.id)
    meta = {"fixtures": a.fixtures, "project": a.project}

    def strategies(name: str, s: StateStore):
        if name == "plain":
            return None
        return SmartStrategy(Planner(st.repo, source=trace_source(meta=meta)), s)

    res = compare_strategies(st, str(store.base), make_runner, strategies)
    print(format_comparison(res))
    st.metrics["comparison"] = res
    store.save(st)
    return 0


def _report(a: argparse.Namespace, store: StateStore) -> int:
    from .report import open_pr, write_reports
    if a.confirm_open_pr and not a.open_pr:
        print("error: --confirm-open-pr requires --open-pr", file=sys.stderr)
        return 2
    st = store.load(a.id)
    for p in write_reports(st, a.out, a.format):
        print(f"wrote {p}")
    if a.open_pr:
        try:
            open_pr(st, st.repo, draft=True if a.draft else None, confirm=a.confirm_open_pr)
        except (ValueError, RuntimeError) as e:
            print(f"error: {e}", file=sys.stderr)
            return 1
        if a.confirm_open_pr and st.status in ("verifying", "fixing", "culprit_found"):
            store.set_status(st, "reported")
    return 0
"""Verifier. This chunk: the revert test that proves the culprit. (Fix verification hooks arrive in chunk 11.)

Revert test: in a fresh worktree at the investigated HEAD, `git revert --no-commit <culprit>`, snapshot the result as a
throwaway commit (so the Runner, cache and worktree machinery work unchanged), run the suite cases on it and require
the regression to disappear: pass rate back to the good-commit level within `tolerance`.

  * revert conflicts   -> abort, retry with only the culprit's hunks that still apply (`git apply -R --reject`),
                          flag "revert conflicts" and cap confidence. Nothing applicable -> inconclusive (None).
  * revert does not fix -> the culprit is probably wrong or there are several regressions: confidence low and the
                          "multiple regressions likely" flag.
"""
from __future__ import annotations

import os
import subprocess
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

from .bisect import COST_PER_RUN_USD
from .culprit import analyze_culprit
from .intake import TraceSource
from .models import BisectState, CommitResult, CulpritReport
from .runner import Runner, worktree
from .state import StateStore
from .tracing import step_span

REVERT_CONFLICTS = "revert conflicts"
MULTI_REGRESSION_FLAG = "multiple regressions likely: reverting the culprit did not remove the regression"
TOLERANCE = 0.1  # pass rate may sit this far below the good-commit level (the confidence band)
_LEVELS = ["low", "medium", "high"]
# fixed identity and dates make the throwaway commit's sha a pure function of (HEAD tree, culprit): resume-safe cache
_GIT_ENV = {"GIT_AUTHOR_NAME": "agentbisect", "GIT_AUTHOR_EMAIL": "agentbisect@localhost",
            "GIT_COMMITTER_NAME": "agentbisect", "GIT_COMMITTER_EMAIL": "agentbisect@localhost",
            "GIT_AUTHOR_DATE": "2000-01-01T00:00:00Z", "GIT_COMMITTER_DATE": "2000-01-01T00:00:00Z"}


def downgrade(conf: str, steps: int = 1) -> str:
    i = _LEVELS.index(conf) if conf in _LEVELS else 0
    return _LEVELS[max(0, i - steps)]


@dataclass
class RevertBuild:
    sha: str | None  # throwaway commit holding HEAD with the culprit reverted; None when nothing could be reverted
    kind: str  # clean | partial | conflict | empty
    detail: str = ""
    rejected: int = 0


def _git(wt: Path, *args: str, stdin: str | None = None) -> subprocess.CompletedProcess:
    return subprocess.run(["git", "-C", str(wt), *args], capture_output=True, text=True, input=stdin,
                          env={**os.environ, **_GIT_ENV})


def _reset(wt: Path) -> None:
    _git(wt, "revert", "--abort")
    _git(wt, "reset", "--hard", "HEAD", "-q")
    _git(wt, "clean", "-fdxq")


def _snapshot(wt: Path, culprit: str) -> str | None:
    """Commit whatever the worktree now holds on top of HEAD; None if the tree is unchanged."""
    _git(wt, "add", "-A")
    if _git(wt, "diff", "--cached", "--quiet").returncode == 0:
        return None
    p = _git(wt, "commit", "-q", "--no-verify", "-m", f"agentbisect revert test of {culprit}")
    if p.returncode != 0:
        raise RuntimeError(f"could not snapshot reverted tree: {p.stderr.strip()[-200:]}")
    return _git(wt, "rev-parse", "HEAD").stdout.strip()


def build_reverted_commit(repo: Path, culprit: str, head: str, worktree_root: str | None = None) -> RevertBuild:
    with worktree(repo, head, worktree_root) as wt:
        parents = _git(wt, "rev-list", "--parents", "-n", "1", culprit).stdout.split()[1:]
        if not parents:
            return RevertBuild(None, "conflict", "culprit is a root commit: nothing to revert to")
        mainline = ["-m", "1"] if len(parents) > 1 else []
        p = _git(wt, "revert", "--no-commit", *mainline, culprit)
        if p.returncode == 0:
            sha = _snapshot(wt, culprit)
            if sha is None:
                return RevertBuild(None, "empty", "reverting the culprit changes nothing at HEAD (already undone?)")
            return RevertBuild(sha, "clean")
        err = (p.stderr or p.stdout).strip()
        _reset(wt)
        # Conflicts: reverse-apply only the culprit hunks that still fit, leave the rest rejected.
        patch = _git(wt, "diff", parents[0], culprit).stdout
        a = _git(wt, "apply", "-R", "--reject", "--whitespace=nowarn", stdin=patch)
        rejected = a.stderr.count("Rejected hunk")
        for junk in wt.rglob("*.rej"):
            junk.unlink()
        sha = _snapshot(wt, culprit)
        if sha is None:
            return RevertBuild(None, "conflict", f"git revert conflicted and no hunk could be reverted: {err[-200:]}",
                               rejected)
        return RevertBuild(sha, "partial", f"git revert conflicted; reverted the hunks that still apply "
                                           f"({rejected} rejected): {err[-160:]}", rejected)


@dataclass
class RevertOutcome:
    passed: bool | None
    confidence: str
    flags: list[str] = field(default_factory=list)
    details: dict[str, Any] = field(default_factory=dict)


def decide_revert(rep: CulpritReport, build: RevertBuild, res: CommitResult | None, baseline: float | None,
                  bad_rate: float | None, good_min: float, tolerance: float = TOLERANCE) -> RevertOutcome:
    conf, flags = rep.confidence or "medium", []
    d: dict[str, Any] = {"kind": build.kind, "detail": build.detail, "rejected_hunks": build.rejected,
                         "baseline_pass_rate": baseline, "culprit_pass_rate": bad_rate}
    if build.kind in ("conflict", "partial"):
        flags.append(REVERT_CONFLICTS)
    if res is None or res.verdict == "skip" or res.pass_rate is None:
        d["reverted_verdict"] = res.verdict if res else None
        d["reason"] = (res.reason if res else build.detail) or "revert test could not be evaluated"
        return RevertOutcome(None, downgrade(conf), flags, d)
    d.update(reverted_pass_rate=res.pass_rate, reverted_verdict=res.verdict, reverted_trace_ids=res.trace_ids[:5])
    target = (baseline if baseline is not None else good_min) - tolerance
    fixed = res.pass_rate >= target and (bad_rate is None or res.pass_rate > bad_rate)
    d["target_pass_rate"] = round(target, 4)
    if not fixed:
        flags.append(MULTI_REGRESSION_FLAG)
        return RevertOutcome(False, "low", flags, d)
    if build.kind == "partial":  # proof stands but the revert was not the whole commit: one notch down
        conf = downgrade(conf)
    return RevertOutcome(True, conf, flags, d)


def revert_test(st: BisectState, runner: Runner, sha: str | None = None) -> tuple[RevertOutcome, int]:
    """Run the revert test for `sha` (default: the recorded culprit). Returns (outcome, eval rounds used)."""
    sha = sha or (st.culprit.sha if st.culprit else None)
    if not sha:
        raise ValueError("no culprit to revert-test")
    rep = st.culprit if st.culprit and st.culprit.sha == sha else CulpritReport(sha=sha)
    repo = Path(st.repo)
    head = _git(repo, "rev-parse", "--verify", f"{st.bad_sha or 'HEAD'}^{{commit}}").stdout.strip()
    with step_span("revert_test", culprit=sha, head=head):
        build = build_reverted_commit(repo, sha, head, runner.cfg.worktree_root)
        res, before = None, runner.eval_rounds
        if build.sha:
            res = runner.evaluate_commit(build.sha, f"{st.id}-revert", list(st.spec.cases) if st.spec else None)
    good = st.results.get(st.good_sha or "")
    bad = st.results.get(sha)
    out = decide_revert(rep, build, res, good.pass_rate if good else None, bad.pass_rate if bad else None,
                        runner.cfg.good_min)
    out.details["reverted_commit"] = build.sha
    return out, runner.eval_rounds - before


def confirm_culprit(store: StateStore, st: BisectState, runner: Runner | None = None, *,
                    source: TraceSource | None = None, **analyst_kw: Any) -> CulpritReport:
    """Explain + prove the culprit found by the bisect. Idempotent and resume-safe: each stage is a begin/end step and
    is skipped when already recorded. Status stays `culprit_found` (the Fixer stage moves it on)."""
    from .bisect import make_runner
    if not st.culprit:
        raise ValueError("investigation has no culprit")
    sha = st.culprit.sha
    if not st.culprit.analyzed:
        store.begin_step(st, "culprit_analysis", sha=sha)
        st.culprit = analyze_culprit(st, sha, source=source, **analyst_kw)
        store.end_step(st)
    if "revert_test" not in st.metrics:
        runner = runner or make_runner(store, st)
        store.begin_step(st, "revert_test", sha=sha)
        out, rounds = revert_test(st, runner)
        rep = st.culprit
        rep.revert_test_passed, rep.confidence = out.passed, out.confidence
        rep.flags = list(dict.fromkeys([*rep.flags, *out.flags]))
        rep.revert_details = {**rep.revert_details, **out.details}
        m = st.metrics
        m["revert_test"] = {"passed": out.passed, "eval_rounds": rounds, **{k: out.details.get(k) for k in (
            "kind", "baseline_pass_rate", "reverted_pass_rate", "culprit_pass_rate")}}
        m["eval_rounds"] = m.get("eval_rounds", 0) + rounds
        m["cost_usd"] = round(m["eval_rounds"] * COST_PER_RUN_USD, 4)
        for f in out.flags:
            if f not in m.setdefault("warnings", []):
                m["warnings"].append(f)
        store.end_step(st)
    return st.culprit


def describe_revert(st: BisectState) -> list[str]:
    """Lines for `agentbisect status`."""
    c = st.culprit
    if not c:
        return []
    r = {True: "PASSED (regression disappears)", False: "FAILED (regression remains)",
         None: "not run" if "revert_test" not in st.metrics else "inconclusive"}[c.revert_test_passed]
    lines = [f"  culprit: {c.sha} (confidence {c.confidence or '?'})",
             f"  revert test: {r}" + (f"  eval rounds={st.metrics['revert_test']['eval_rounds']}"
                                      if "revert_test" in st.metrics else "")]
    rt = st.metrics.get("revert_test") or {}
    if rt.get("reverted_pass_rate") is not None:
        lines.append(f"    pass rate: culprit {rt.get('culprit_pass_rate')} -> reverted {rt['reverted_pass_rate']} "
                     f"(good commit {rt.get('baseline_pass_rate')})")
    if c.intent_source:
        lines.append(f"  intent source: {c.intent_source}")
    for f in c.flags:
        lines.append(f"  flag: {f}")
    return lines

    except (OSError, subprocess.SubprocessError) as e:
