                debug_dump: str | None = None) -> int:
    px = LLMProxy(claude_bin=claude_bin, concurrency=concurrency, debug_dump=debug_dump,
                  cache_dir=(cache_dir or DEFAULT_CACHE_DIR) if cache else None)
    px.serve(port)
