          f"use ANTHROPIC_BASE_URL={px.url} ANTHROPIC_API_KEY={DUMMY_API_KEY}; GET /stats for counters", flush=True)
    try:
        while True:
            time.sleep(3600)
    except KeyboardInterrupt:
        px.stop()
        print(json.dumps(px.stats.snapshot()))
    return 0
